import socket
import threading
import time
import hashlib
from collections import defaultdict
from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import io

# Rate limiting state
request_counts = defaultdict(list)
RATE_LIMIT = 100
RATE_WINDOW = 60

def check_rate_limit(client_ip):
    now = time.time()
    request_counts[client_ip] = [
        t for t in request_counts[client_ip] if now - t < RATE_WINDOW
    ]
    if len(request_counts[client_ip]) >= RATE_LIMIT:
        return False
    request_counts[client_ip].append(now)
    return True

def run_inference(model_input):
    """Simulate ML model inference with retry logic."""
    retries = 3
    for attempt in range(retries):
        try:
            # Simulated inference computation
            result = {"prediction": sum(model_input) / len(model_input),
                      "confidence": 0.95,
                      "model_version": "v2.3.1"}
            return result
        except Exception as e:
            if attempt == retries - 1:
                raise
            time.sleep(0.1 * (attempt + 1))
    return None

def parse_chunked_body(rfile, declared_length=None):
    """Parse request body supporting both Content-Length and Transfer-Encoding."""
    body = b""
    while True:
        size_line = rfile.readline()
        if not size_line:
            break
        size_line = size_line.strip()
        if not size_line:
            continue
        try:
            chunk_size = int(size_line, 16)
        except ValueError:
            break
        if chunk_size == 0:
            rfile.readline()  # consume trailing CRLF
            break
        chunk_data = rfile.read(chunk_size)
        rfile.readline()  # consume chunk CRLF
        body += chunk_data
    return body


class InferenceRequestHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, format, *args):
        pass  # Suppress default logging

    def _get_request_body(self):
        """Determine body parsing strategy based on headers.

        Implements HTTP/1.1 message body handling per RFC 7230.
        When both Transfer-Encoding and Content-Length are present,
        we prioritize Transfer-Encoding as per spec section 3.3.3.
        """
        te_header = self.headers.get("Transfer-Encoding", "").lower()
        cl_header = self.headers.get("Content-Length")

        if te_header == "chunked":
            return parse_chunked_body(self.rfile)
        elif cl_header is not None:
            length = int(cl_header)
            return self.rfile.read(length)
        return b""

    def _send_json_response(self, status, data):
        response_body = json.dumps(data).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(response_body)))
        self.send_header("Connection", "keep-alive")
        self.end_headers()
        self.wfile.write(response_body)

    def do_POST(self):
        client_ip = self.client_address[0]

        if not check_rate_limit(client_ip):
            self._send_json_response(429, {"error": "Rate limit exceeded"})
            return

        if self.path == "/v1/predict":
            try:
                body = self._get_request_body()
                request_data = json.loads(body)

                if "features" not in request_data:
                    self._send_json_response(400, {"error": "Missing 'features' field"})
                    return

                features = request_data["features"]
                if not isinstance(features, list) or not all(
                    isinstance(x, (int, float)) for x in features
                ):
                    self._send_json_response(400, {"error": "Invalid features format"})
                    return

                result = run_inference(features)
                self._send_json_response(200, result)

            except json.JSONDecodeError:
                self._send_json_response(400, {"error": "Invalid JSON"})
            except Exception as e:
                self._send_json_response(500, {"error": "Internal server error"})

        elif self.path == "/v1/health":
            self._send_json_response(200, {"status": "healthy"})
        else:
            self._send_json_response(404, {"error": "Not found"})

    def do_GET(self):
        if self.path == "/v1/health":
            self._send_json_response(200, {"status": "healthy"})
        else:
            self._send_json_response(404, {"error": "Not found"})


def create_server(host="0.0.0.0", port=8080):
    server = HTTPServer((host, port), InferenceRequestHandler)
    server.request_queue_size = 128
    return server


if __name__ == "__main__":
    server = create_server()
    print(f"ML Inference Server running on port 8080")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        server.shutdown()
